const inp = $('Gateway Input').first().json;
let index = null;
try { index = JSON.parse($json.data ?? $json.body ?? $json.gemini_text ?? ''); } catch (e) {}
if (!index) { try { index = typeof $json === 'object' && $json.skills ? $json : null; } catch (e) {} }
const skills = (index && index.skills) || [];
const skill = skills.find(s => s.id === inp.skill_id && s.status === 'approved');
let payload = {};
try { payload = inp.payload ? JSON.parse(inp.payload) : {}; } catch (e) { payload = { _raw: inp.payload }; }
const allowed = skill ? (skill.allowed_services || []) : [];
const denied = !skill || !allowed.includes(inp.service);
return [{ json: {
  service: inp.service, skill_id: inp.skill_id, employee_id: inp.employee_id,
  session_id: inp.session_id || '', payload,
  denied, allowed_services: allowed,
  skill_meta: skill ? { approval_chain: skill.approval_chain, auto_execute: skill.auto_execute,
    sla_hours: skill.sla_hours, title_ar: skill.title_ar } : null,
} }];

return [{ json: { ...$json, result: { error: 'SERVICE_DENIED_BY_GOVERNANCE',
  message: 'هذه الخدمة غير مصرح بها لهذه المهارة وفق السجل المعتمد.',
  allowed_services: $json.allowed_services } } }];

return [{ json: { ...$json, result: { error: 'SERVICE_NOT_IMPLEMENTED',
  message: 'الخدمة مسموحة في المهارة لكنها غير مبنية في البوابة بعد - أبلغ الموظف بذلك.',
  service: $json.service } } }];

const j = $('Gate Check').first().json;
const rows = $input.all().map(i => i.json);
const e = rows.find(r => r.employee_id === j.employee_id);
if (!e) return [{ json: { ...j, result: { error: 'EMPLOYEE_NOT_FOUND' } } }];
return [{ json: { ...j, result: {
  employee_id: e.employee_id, name_ar: e.name_ar, name_en: e.name_en, role: e.role,
  department: e.department, grade: e.grade, manager_id: e.manager_id, status: e.status,
  joined_date: e.joined_date,
} } }];

const j = $('Gate Check').first().json;
const rows = $input.all().map(i => i.json);
const b = rows.find(r => r.employee_id === j.employee_id);
if (!b) return [{ json: { ...j, result: { error: 'BALANCE_NOT_FOUND' } } }];
return [{ json: { ...j, result: {
  annual_total: +b.annual_total, annual_used: +b.annual_used,
  annual_remaining: +b.annual_total - +b.annual_used,
  sick_total: +b.sick_total, sick_used: +b.sick_used,
  sick_remaining: +b.sick_total - +b.sick_used,
} } }];

const j = $('Gate Check').first().json;
const emps = $('Read Employees (salary)').all().map(i => i.json);
const txns = $input.all().map(i => i.json);
const e = emps.find(r => r.employee_id === j.employee_id);
if (!e) return [{ json: { ...j, result: { error: 'EMPLOYEE_NOT_FOUND' } } }];
const month = new Date().toISOString().slice(0, 7);
const certs = txns.filter(t => t.employee_id === j.employee_id && t.skill_id === 'salary-certificate'
  && String(t.ts || '').startsWith(month) && t.status === 'executed').length;
return [{ json: { ...j, result: {
  name_ar: e.name_ar, name_en: e.name_en, role: e.role, grade: e.grade,
  joined_date: e.joined_date, status: e.status,
  monthly_salary_aed: +e.monthly_salary_aed, allowances_aed: +e.allowances_aed,
  certificates_issued_this_month: certs, monthly_limit: 3,
} } }];

const j = $('Gate Check').first().json;
const pol = $input.all().map(i => i.json);
const txns = $('Read Transactions (policy)').all().map(i => i.json);
const cat = j.payload.category || '';
const p = pol.find(r => r.category === cat);
if (!p) return [{ json: { ...j, result: { error: 'UNKNOWN_CATEGORY', categories: pol.map(r => r.category) } } }];
const month = new Date().toISOString().slice(0, 7);
let spent = 0;
for (const t of txns) {
  if (t.employee_id !== j.employee_id || t.skill_id !== 'expense-claim') continue;
  if (!String(t.ts || '').startsWith(month)) continue;
  if (!['executed', 'awaiting_manager', 'awaiting_finance'].includes(t.status)) continue;
  try { const pl = JSON.parse(t.payload_json || '{}'); if (pl.category === cat) spent += +pl.amount_aed || 0; } catch (e) {}
}
return [{ json: { ...j, result: {
  category: cat, monthly_cap_aed: +p.monthly_cap_aed,
  receipt_required_above: +p.receipt_required_above,
  spent_this_month_aed: Math.round(spent * 100) / 100,
  remaining_this_month_aed: Math.round((+p.monthly_cap_aed - spent) * 100) / 100,
  notes: p.notes || '',
} } }];

const j = $('Gate Check').first().json;
const rows = $input.all().map(i => i.json);
const e = rows.find(r => r.employee_id === j.employee_id);
if (!e) return [{ json: { ...j, result: { error: 'EMPLOYEE_NOT_FOUND' } } }];
const roles = String(e.it_roles || '').split(';').map(s => s.trim()).filter(Boolean);
return [{ json: { ...j, result: { current_access: roles } } }];

const j = $('Gate Check').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.system_id);
const q = (j.payload.system_id || j.payload.query || '').toLowerCase();
const hit = rows.filter(r => !q || r.system_id.toLowerCase().includes(q)
  || String(r.name_ar).includes(j.payload.system_id || j.payload.query || '')
  || String(r.name_en).toLowerCase().includes(q));
return [{ json: { ...j, result: { systems: hit.map(r => ({
  system_id: r.system_id, name_ar: r.name_ar, name_en: r.name_en,
  sensitivity: r.sensitivity, allowed_roles: String(r.allowed_roles || '').split(';').filter(Boolean),
})) } } }];

function workingDays(startISO, endISO) {
  const s = new Date(startISO + 'T12:00:00Z'), e = new Date(endISO + 'T12:00:00Z');
  if (isNaN(s) || isNaN(e) || e < s) return null;
  let n = 0; const d = new Date(s);
  while (d <= e) { const w = d.getUTCDay(); if (w !== 6 && w !== 0) n++; d.setUTCDate(d.getUTCDate() + 1); }
  return n;
}
const j = $('Gate Check').first().json;
const txns = $input.all().map(i => i.json);
const emps = $('Read Employees (overlap)').all().map(i => i.json);
const me = emps.find(r => r.employee_id === j.employee_id) || {};
const team = emps.filter(r => r.department === me.department && r.employee_id !== j.employee_id)
  .map(r => r.employee_id);
const s = j.payload.start_date, e = j.payload.end_date;
const overlaps = [];
for (const t of txns) {
  if (t.skill_id !== 'leave-request') continue;
  if (!['awaiting_manager', 'executed'].includes(t.status)) continue;
  if (!team.includes(t.employee_id)) continue;
  try {
    const pl = JSON.parse(t.payload_json || '{}');
    if (pl.start_date <= e && pl.end_date >= s) overlaps.push({ employee: t.employee_name,
      start_date: pl.start_date, end_date: pl.end_date, status: t.status });
  } catch (er) {}
}
return [{ json: { ...j, result: { requested_working_days: workingDays(s, e),
  team_overlaps: overlaps } } }];

const j = $('Gate Check').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.memory_id);
const mine = rows.filter(r => r.status === 'active' && (r.scope === 'org'
  || (r.scope === 'employee' && r.subject_id === j.employee_id)));
return [{ json: { ...j, result: { memories: mine.map(m => ({
  memory_id: m.memory_id, scope: m.scope, content: m.content })) } } }];

const j = $('Gate Check').first().json;
const LIMIT = 2200;  // characters, model-independent - the whole GC policy
const rows = $input.all().map(i => i.json).filter(r => r && r.memory_id);
const p = j.payload || {};
const scope = p.scope === 'org' ? 'org' : 'employee';
const subject = scope === 'org' ? '' : (p.subject_id || j.employee_id);
const scoped = rows.filter(r => r.status === 'active' && r.scope === scope
  && (scope === 'org' || r.subject_id === subject));
const used = scoped.reduce((n, r) => n + String(r.content || '').length, 0);
const action = p.action || 'add';
const now = new Date().toISOString();
if (action === 'remove' || action === 'replace') {
  const target = scoped.find(r => r.memory_id === p.memory_id
    || (p.match && String(r.content || '').includes(p.match)));
  if (!target) return [{ json: { ...j, result: { error: 'MEMORY_NOT_FOUND' } } }];
  const row = { ...target, updated_at: now };
  if (action === 'remove') { row.status = 'retired'; }
  else { row.content = String(p.content || '').slice(0, 400); }
  return [{ json: { ...j, memory_row: row,
    result: { ok: true, action, memory_id: row.memory_id } } }];
}
const content = String(p.content || '').trim().slice(0, 400);
if (!content) return [{ json: { ...j, result: { error: 'EMPTY_CONTENT' } } }];
if (scoped.some(r => r.content === content))
  return [{ json: { ...j, result: { ok: true, deduped: true } } }];
if (used + content.length > LIMIT) {
  return [{ json: { ...j, result: { error: 'MEMORY_BUDGET_EXCEEDED',
    usage: used + '/' + LIMIT,
    message: 'الذاكرة ممتلئة. ادمج مدخلات متداخلة أو احذف الأقل أهمية من القائمة ثم أعد المحاولة في الدور نفسه.',
    current_entries: scoped.map(r => ({ memory_id: r.memory_id, content: r.content }))
  } } }];
}
const row = { memory_id: 'MEM-' + Date.now(), scope, subject_id: subject,
  content, source: p.source || 'reflection', status: 'active', use_count: '0',
  created_at: now, updated_at: now };
return [{ json: { ...j, memory_row: row, result: { ok: true, action: 'add',
  memory_id: row.memory_id, usage: (used + content.length) + '/' + LIMIT } } }];

const j = $('Gate Check').first().json;
const p = j.payload || {};
const now = new Date().toISOString();
const text = String(p.proposed_text || '').trim().slice(0, 600);
if (!text || !p.skill_id)
  return [{ json: { ...j, result: { error: 'SKILL_ID_AND_TEXT_REQUIRED' } } }];
const rows = $input.all().map(i => i.json).filter(r => r && r.patch_id);
if (rows.some(r => r.status === 'pending' && r.skill_id === p.skill_id
  && r.proposed_text === text))
  return [{ json: { ...j, result: { ok: true, deduped: true } } }];
const row = { patch_id: 'PATCH-' + Date.now(), skill_id: p.skill_id,
  kind: p.kind || 'add_rule', proposed_text: text,
  rationale: String(p.rationale || '').slice(0, 400),
  evidence: String(p.evidence || '').slice(0, 200), status: 'pending',
  created_by: 'agent', reviewed_by: '', review_note: '',
  created_at: now, updated_at: now };
return [{ json: { ...j, patch_row: row, result: { ok: true, patch_id: row.patch_id,
  status: 'pending', message: 'اقتراح مسجّل بانتظار اعتماد مالك الإجراء' } } }];

const j = $('Gate Check').first().json;
const emps = $input.all().map(i => i.json);
const me = emps.find(r => r.employee_id === j.employee_id) || {};
const now = new Date();
const txn_id = 'TXN-' + now.getTime();
const meta = j.skill_meta || { approval_chain: ['manager'], auto_execute: false, sla_hours: 48 };
const chain = meta.approval_chain || []; // governed chain ONLY - never from the model
for (const k of Object.keys(j.payload)) if (k.startsWith('_')) delete j.payload[k];
const auto = chain.length === 0; // empty chain = instant execution
let output_ref = '';
if (auto && j.skill_id === 'salary-certificate') output_ref = 'CERT-' + String(now.getTime()).slice(-6);
const status = auto ? 'executed' : 'awaiting_' + chain[0];
const row = {
  txn_id, ts: now.toISOString(), employee_id: j.employee_id,
  employee_name: me.name_ar || j.employee_id, skill_id: j.skill_id,
  type_ar: meta.title_ar || j.skill_id,
  payload_json: JSON.stringify(j.payload), status,
  approval_chain: chain.join(';'), chain_pos: 0,
  current_approver: chain[0] || '', decision_note: '', output_ref,
  sla_hours: meta.sla_hours || 48, updated_at: now.toISOString(),
};
return [{ json: { ...j, txn_row: row, result: { txn_id, status, output_ref,
  approval_chain: chain, message: auto ? 'نُفّذت المعاملة فورًا' : 'أُرسلت لسلسلة الاعتماد' } } }];

const j = $json;
return [{ json: {
  ts: new Date().toISOString(), session_id: j.session_id || '',
  employee_id: j.employee_id || '', skill_id: j.skill_id || '',
  service: j.service || '', request_json: JSON.stringify(j.payload || {}),
  result_summary: (j.result && j.result.error) ? ('DENIED/ERROR: ' + j.result.error)
    : ('OK ' + JSON.stringify(j.result || {}).slice(0, 160)),
} }];

const src = $('Build Audit Row').first().json;
// find the full item that produced the audit row
let full = null;
for (const n of ['Denied Result','svc: get_employee_profile','svc: get_leave_balance',
  'svc: get_salary_record','svc: get_expense_policy','svc: get_it_roles',
  'svc: get_system_catalog','svc: check_leave_overlap','Carry Submit Result',
  'Carry Memory Result','Carry Patch Result','svc: read_memory','svc: not_implemented']) {
  try { const it = $(n).first(); if (it && it.json && it.json.result) { full = it.json; break; } } catch (e) {}
}
return [{ json: { service: src.service, result: (full && full.result) || { error: 'NO_RESULT' } } }];
